{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Approaching the ruined city.",
      "visual_description": "A vast ruined city sprawls under a grey sky, crumbled towers and broken royal banners flapping in the wind.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Meeting the oracle lamp at the outer gate.",
      "visual_description": "At the rusted castle gates, the oracle lamp flickers with a single glowing eye, warning of dangers ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The sleeping tax collector blocks the path.",
      "visual_description": "The sleeping tax collector dozes on a pile of stamped papers, blocking the main road into the city.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 4,
      "caption": "Tin fox scouts a cursed tower.",
      "visual_description": "The tin fox scurries up to a twisted tower covered in dark vines, its blue eyes scanning for danger.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Mara reads the old royal banners.",
      "visual_description": "Mara inspects a tattered royal banner, using her compass to align the faded symbols with her map.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Frightened townspeople huddle in a square.",
      "visual_description": "A group of frightened townspeople cluster in a square, whispering as the glass diver passes.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol marches past.",
      "visual_description": "A line of armored figures with blank visors marches in lockstep down a cracked avenue.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp warns of a magic door.",
      "visual_description": "The oracle lamp's flame glows red as it warns about a looming magic door etched with shifting runes.",
      "characters": ["glass_diver", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Glass diver swims through a mirror into a locked chamber.",
      "visual_description": "The glass diver presses his helmet against a cracked mirror and passes through into a dusty chamber filled with locked chests.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara navigates a labyrinth of fallen pillars.",
      "visual_description": "Mara weaves between colossal fallen pillars, inking a path onto her map as the tin fox follows.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector stirs and offers a clue.",
      "visual_description": "Half-asleep, the tax collector mumbles a clue about a hidden passage, then sinks back into slumber.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Tin fox disarms a trap at the old market.",
      "visual_description": "The tin fox triggers a pressure plate and quickly winds its tail to jam the gear mechanism, stopping a collapsing awning.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Oracle lamp illuminates the rumored lair.",
      "visual_description": "The oracle lamp's light reveals a cavernous lair beneath a tower, filled with hoarded trinkets and old bones.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Glass diver retrieves the captive from a mirrored cell.",
      "visual_description": "The glass diver swims through a wall of mirrors into a cell and helps a dazed figure to safety.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The armored patrol corners the group.",
      "visual_description": "Armored figures block the exit from the tower, raising gauntleted hands in unison.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Mara finds a secret route through a collapsed wall.",
      "visual_description": "Mara's compass needle spins and points to a hidden opening in a rubble-choked wall.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the final bridge.",
      "visual_description": "The team sprints across a long stone bridge as the city crumbles behind them, the oracle lamp swinging wildly.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe beyond the bridge.",
      "visual_description": "They stand on the far side, looking back at the ruined city as dust settles, the glass diver removing his helmet.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

